import { Component, computed, ElementRef, HostBinding, inject } from '@angular/core';

const KEY = 'tabIndex';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
})
export class PctAvatar {
  private readonly el = inject(ElementRef);
  constructor() {
    this.el.nativeElement[KEY] = 5;
  }
}
